def transform(grid):
    h,w=len(grid),len(grid[0]); bg=max({v for row in grid for v in row},key=lambda v:sum(row.count(v) for row in grid)); out=[row[:] for row in grid]
    for r in range(h):
        cols=[c for c,v in enumerate(grid[r]) if v!=bg]
        for a,b in zip(cols,cols[1:]):
            for c in range(a+1,b): out[r][c]=3
    for c in range(w):
        rows=[r for r in range(h) if grid[r][c]!=bg]
        for a,b in zip(rows,rows[1:]):
            for r in range(a+1,b): out[r][c]=3
    return out
